use vstd::prelude::*;

verus! {

/// Mathematical feasibility condition (over nats, avoiding overflow).
spec fn feasible(a: nat, b: nat, n: nat, m: nat) -> bool {
    // Total cookies must cover total needed servings: n regular (1 each) + m special (2 each)
    // and each pile must individually cover the special guests (one from each pile).
    a + b >= n + m && a >= m && b >= m
}

/// Decide whether two cookie piles can serve n regular guests and m special guests.
/// - regular guest: needs 1 cookie from either pile
/// - special guest: needs 1 from pile A and 1 from pile B (so requires a>=m and b>=m)
fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> (result: bool)
    requires
        n + m > 0,
    ensures
        result == feasible(a as nat, b as nat, n as nat, m as nat),
{
    // Use u16 intermediates to avoid any possibility of u8 overflow in the implementation.
    let au: u16 = a as u16;
    let bu: u16 = b as u16;
    let nu: u16 = n as u16;
    let mu: u16 = m as u16;

    let total_ok: bool = au + bu >= nu + mu;
    let per_pile_ok: bool = au >= mu && bu >= mu;
    let result: bool = total_ok && per_pile_ok;

    // Connect the computed booleans back to the nat-level spec.
    assert(result == (au + bu >= nu + mu && au >= mu && bu >= mu));
    assert(au + bu >= nu + mu <==> (a as nat + b as nat >= n as nat + m as nat));
    assert(au >= mu <==> (a as nat >= m as nat));
    assert(bu >= mu <==> (b as nat >= m as nat));

    assert(result == feasible(a as nat, b as nat, n as nat, m as nat));
    result
}

} // verus!

